function convertTo2DArray(str) {
  // 将输入字符串按行分割
  const rows = str.split('\n');

  // 用于存储最终二维数组的变量
  const array2D = [];

  // 遍历每一行
  rows.forEach(row => {
    // 去除行尾的换行符并按逗号分割
    const columns = row.replace('\r', '').split(',');

    // 处理每一列，将空字符串转换为0
    const processedColumns = columns.map(column => {
      return column === '' ? 0 : column;
    });

    // 将处理后的列数组添加到二维数组中
    array2D.push(processedColumns);
  });

  return array2D;
}

