function convertIntsToFloats(obj) {
    var result = {};

    for (var key in obj) {
        if (typeof obj[key] === 'number' && Number.isInteger(obj[key]) && obj[key] >= 1e8) {
            var buffer = new ArrayBuffer(4);
            var intView = new Int32Array(buffer);
            var floatView = new Float32Array(buffer);

            intView[0] = obj[key];
            result[key] = floatView[0];
        } else {
            result[key] = obj[key];
        }
    }

    return result;
}
var obj = msg.payload 
msg.payload = convertIntsToFloats(obj)
return msg;

