function constrainObjectValues(obj, minValue) {
    for (let key in obj) {
        if (obj.hasOwnProperty(key)) {
            let value = obj[key];

            if (value < minValue) {
                obj[key] = minValue;
            }
        }
    }

    return obj;
}
