//两个obj相乘
function objectMultiplication(obj1, obj2) {
    const difference = {};

    for (let key in obj1) {
        if (obj1.hasOwnProperty(key) && obj2.hasOwnProperty(key)) {
            difference[key] = obj1[key] * obj2[key];
        }
    }

    return difference;
}
//object中的value都乘以给定的数值
function multiplyObjectValues(obj, multiplier) {
    const result = {};

    for (let key in obj) {
        if (obj.hasOwnProperty(key)) {
            result[key] = obj[key] * multiplier;
        }
    }

    return result;
}
