function clean(v) {
    const n = Number(v);
    if (!Number.isFinite(n)) return 0;
    return Number(Math.max(0, n).toFixed(2));
}

function push(msgs, topic, value) {
    msgs.push({
        topic,
        payload: clean(value)
    });
}

