const manual = global.get("张家港手动设定") || {};
const setting = global.get("设定读取") || {};
const raw = global.get("PLC原始数据") || {};
const category = categoryName ? (global.get(categoryName) || {}) : {};

function readValue() {
  if (KIND === "set" && Object.prototype.hasOwnProperty.call(manual, KEY)) return manual[KEY];
  if (KIND === "set" && Object.prototype.hasOwnProperty.call(setting, KEY)) return setting[KEY];
  if (Object.prototype.hasOwnProperty.call(category, KEY)) return category[KEY];
  if (Object.prototype.hasOwnProperty.call(raw, KEY)) return raw[KEY];
  return DEFAULT_VALUE;
}

const n = Number(readValue());
msg.payload = Number.isFinite(n) ? Number(n.toFixed(2)) : DEFAULT_VALUE;
return msg;

