const key = msg.topic;
if (!key) return null;
const state = global.get("张家港手动开关") || {};
state[key] = msg.payload;
global.set("张家港手动开关", state);

// Also mirror device on/off states into global.开关 so existing display logic can reuse them during demos.
if (key.startsWith("反馈_")) {
  const sw = Object.assign({}, global.get("开关") || {});
  sw[key] = msg.payload;
  global.set("开关", sw);
}
return null;

const manual = global.get("张家港手动开关") || {};
msg.payload = manual["系统模式"] || "手动模式";
return msg;

const KEY = "反馈_冷水机组1开关";
const manual = global.get("张家港手动开关") || {};
const actual = Object.assign({}, global.get("PLC原始数据") || {}, global.get("开关") || {});
let value = Object.prototype.hasOwnProperty.call(manual, KEY) ? manual[KEY] : actual[KEY];
const on = value === true || value === 1 || value === "1" || value === "开";
msg.payload = on ? "开" : "关";
return msg;

